import type { Args } from "../context/args"

/** Consume local commands before prompt submission, including on remote connections. */
export async function reconnect(input: { text: string; directory: string; remote: boolean; send?: Args["reconnect"] }) {
  if (!/^\/reconnect(?:\s|$)/.test(input.text.trim())) return
  if (input.remote || !input.send) {
    return {
      ok: false,
      message: "/reconnect is only available in a local CLI session; remote attach/workspaces are unsupported.",
    }
  }
  return input.send({ command: input.text, directory: input.directory })
}

